(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["principles-of-diagnostic-medicine-i-exam-4"]={"title":"Principles of Diagnostic Medicine I Exam 4","sections":[{"id":"scope","title":"How This Exam Is Written","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l17-landmarks","title":"Landmarks You Can Feel (Lecture 17)","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l17-normal-film","title":"The Normal Chest Film","style":"--acc:#3a6797;--acc-bg:#e3eaf0;--acc-zebra:#f1f4f8;--acc-ink:#2d5076"},{"id":"l17-airway","title":"Upper Airway Films","style":"--acc:#8a5a1c;--acc-bg:#efe8df;--acc-zebra:#f7f3ef;--acc-ink:#6c4616"},{"id":"l17-technique","title":"Is It the Film or the Patient?","style":"--acc:#2f5d62;--acc-bg:#e2e8e9;--acc-zebra:#f0f4f4;--acc-ink:#25494c"},{"id":"l17-modalities","title":"Choosing the Study","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l17-safety","title":"Contraindications and Cautions","style":"--acc:#3a6797;--acc-bg:#e3eaf0;--acc-zebra:#f1f4f8;--acc-ink:#2d5076"},{"id":"l17-ct","title":"Reading Computed Tomography","style":"--acc:#8a5a1c;--acc-bg:#efe8df;--acc-zebra:#f7f3ef;--acc-ink:#6c4616"},{"id":"l17-patterns","title":"The Five Patterns","style":"--acc:#2f5d62;--acc-bg:#e2e8e9;--acc-zebra:#f0f4f4;--acc-ink:#25494c"},{"id":"l20-equipment","title":"The Equipment and What Each Test Measures (Lecture 20)","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l20-volumes","title":"The Four Volumes and Four Capacities","style":"--acc:#3a6797;--acc-bg:#e3eaf0;--acc-zebra:#f1f4f8;--acc-ink:#2d5076"},{"id":"l20-spirometry","title":"Spirometry and the Forced Values","style":"--acc:#8a5a1c;--acc-bg:#efe8df;--acc-zebra:#f7f3ef;--acc-ink:#6c4616"},{"id":"l20-indications","title":"Why Order Them","style":"--acc:#2f5d62;--acc-bg:#e2e8e9;--acc-zebra:#f0f4f4;--acc-ink:#25494c"},{"id":"l20-patterns","title":"Obstructive Against Restrictive","style":"--acc:#26384a;--acc-bg:#e1e3e6;--acc-zebra:#f0f1f2;--acc-ink:#1e2c3a"},{"id":"l20-reading","title":"Reading a Report","style":"--acc:#3a6797;--acc-bg:#e3eaf0;--acc-zebra:#f1f4f8;--acc-ink:#2d5076"},{"id":"l20-role","title":"Each Standard Test's Job, and Oxygenation","style":"--acc:#8a5a1c;--acc-bg:#efe8df;--acc-zebra:#f7f3ef;--acc-ink:#6c4616"}],"rows":[{"t":"Reference ranges are GIVEN","d":"“I'm not going to just throw a random number at you” — a creatinine or any value in a stem comes with the range that reads it.","s":0},{"t":"Tests over diagnoses","d":"“More related to the tests themselves”: which study, why, its cautions, and what normal looks like on it.","s":0},{"t":"Next-best-test","d":"In imaging it is a study: radiograph first; angiogram first for a suspected pulmonary embolism; computed tomography when the radiograph is inconclusive; ventilation/perfusion when contrast can't be given.","s":0},{"t":"Images in play","d":"Expect a film or a slice with the vignette. Technique first, then structures, then the pattern.","s":0},{"t":"★ Sternal angle","d":"The manubriosternal joint communicates with the SECOND rib: find the second rib for procedures, then palpate down and count.","s":1},{"t":"★ Nipple line","d":"Corresponds to the FIFTH intercostal space.","s":1},{"t":"Fifth rib","d":"Below the base of the fifth rib are the INFERIOR lobes; above it, the SUPERIOR lobes.","s":1},{"t":"Jugular notch","d":"Deep to it is the TRACHEA.","s":1},{"t":"Larynx","d":"C3 to C6 (the slide; the recording's \"C9\" does not exist). Cricothyroid ligament about 1 centimeter below the laryngeal prominence.","s":1},{"t":"Neck triangles","d":"POSTERIOR triangle: subclavian vein and lung apices. CAROTID triangle: bifurcation of the common carotid. The sternocleidomastoid divides anterior from posterior.","s":1},{"t":"First line","d":"Chest radiographs are the most common radiologic study (radiographs = 75% of images ordered) and almost always FIRST for a pulmonary or cardiac complaint; pain and shortness of breath.","s":2},{"t":"★ Posteroanterior vs anteroposterior","d":"POSTEROANTERIOR = ambulatory, standing. ANTEROPOSTERIOR = supine, HEART MAGNIFIED: do not call it enlarged on that view alone.","s":2},{"t":"★ Aortic knob","d":"The rounded bulge at the top of the left mediastinal border (the aortic arch); pulmonary artery just below, then the left hilum.","s":2},{"t":"★ Costophrenic angles","d":"Sharp Vs where each hemidiaphragm meets the chest wall: \"nice and sharp\" is normal. Gastric bubble under the left hemidiaphragm.","s":2},{"t":"★ Heart size","d":"No more than HALF the posteroanterior span of the chest; one third right of the midline, two thirds left.","s":2},{"t":"★ Hila","d":"Bisect the chest; mostly pulmonary arteries and veins (plus fat, nodes, bronchial walls); LEFT slightly HIGHER; concave, similar size and density.","s":2},{"t":"★ Trachea","d":"Smooth radiopaque border, radiolucent inside, MIDLINE.","s":2},{"t":"The rest of the read","d":"Lungs radiolucent; retrosternal and retrocardiac spaces; only pulmonary arteries and veins as vascular markings; each rib one at a time, both sides; spinous processes midline. Lateral film: thoracic spine has a posterior arch.","s":2},{"t":"Indications","d":"Muffled voice; stridor (wheeze heard from the mouth without a stethoscope); suspected sinus infection; anterior neck pain.","s":3},{"t":"Water's view","d":"Maxillary and frontal sinuses, 45 degrees to the orbitomeatal line. For sinusitis: not really needed, but can confirm it and possibly REDUCE ANTIBIOTIC use.","s":3},{"t":"★ Lateral soft-tissue neck","d":"Trachea = the dark, patent, radiolucent air column. The esophagus sits in the RETROTRACHEAL space and shows NO air: collapsed = NORMAL when not eating.","s":3},{"t":"Bones on the neck film","d":"Slight ANTERIOR curve (cervical lordosis). The body below C7 is partly hidden by the FIRST RIB.","s":3},{"t":"How to read it","d":"Superior to inferior, left to right; airways dark; sinuses air-filled; bones continuous; always symmetry.","s":3},{"t":"Good exposure","d":"Vessels to at least the PERIPHERAL THIRD; paraspinous margins; left hemidiaphragm visible behind the heart.","s":4},{"t":"Overexposed","d":"DARK: thoracic spine, mediastinum, retrocardiac areas and nasogastric/endotracheal tubes show through.","s":4},{"t":"Underexposed","d":"WHITE: small vessels, NO spine and NO mediastinal anatomy.","s":4},{"t":"Inspiration","d":"Domes to the TENTH posterior rib standing (eighth to tenth seated or lying). Few ribs above the diaphragm = poor effort.","s":4},{"t":"★ Rotation","d":"Spinous processes to the clavicle borders. Do NOT use the tracheal shadow (a tube looks the same rotated).","s":4},{"t":"The checklist","d":"Trachea midline or deviated; lungs shadowing or lucency; vessels enlarged; HILA masses or lymphadenopathy; mediastinum width or mass; PLEURA effusion, thickening, calcification; BONES lesions or fractures; soft tissues: don't miss a mastectomy.","s":4},{"t":"Computed tomography first?","d":"ONLY for a suspected pulmonary embolism: the computed tomography ANGIOGRAM. Everything else starts with the radiograph.","s":5},{"t":"Radiograph indications","d":"Chest pain, dyspnea, cough over 6 WEEKS unexplained, unexplained weight loss in any chronic SMOKER, hemoptysis, adventitious sounds, support hardware (lines, tubes, pacemaker).","s":5},{"t":"Computed tomography","d":"Most common reason: an INCONCLUSIVE radiograph with a continuing problem. Also embolism, trauma, chronic obstructive pulmonary and interstitial lung disease, BONE (rib and spine fractures), cancer screening. Head and neck: retropharyngeal abscess or foreign body the radiograph missed.","s":5},{"t":"Contrast is for","d":"VASCULAR pathology (embolism, dissection, aneurysm), focal lesions, the -itis conditions (magnetic resonance superior for vasculitis), METASTASES to lymph nodes.","s":5},{"t":"Ultrasound","d":"Almost exclusively TRAUMA: collapsed lung or fluid (extended focused assessment with sonography for trauma); procedures; NO contraindications. Ribs cast shadows.","s":5},{"t":"★ Ventilation/perfusion","d":"For pulmonary embolism when the angiogram can't be done (CONTRAST ALLERGY); INFERIOR to the angiogram. Ventilation: INHALED technetium-99m. Perfusion: INJECTED technetium-99m macroaggregated albumin. Result: low, medium or high probability.","s":5},{"t":"Positron emission tomography","d":"Higher resolution and sensitivity than single-photon, more cost; usually secondary to the radiograph; mostly for METASTASES; now done with computed tomography for a much CLEARER image.","s":5},{"t":"Magnetic resonance","d":"King of soft tissue, but the lungs' anatomy makes computed tomography first. Used for a mass INCONCLUSIVE on computed tomography, patients who can't have it, vasculopathy (second choice); SUPERIOR to the angiogram for INTRAMURAL HEMATOMA. Inflammation: dark T1, bright T2.","s":5},{"t":"Who reads it","d":"The radiologist gives the official read; the clinician's read is often just for the answer.","s":5},{"t":"★ Radiographs","d":"NO true contraindications. Lifetime limit 100 millisieverts = about 10,000 chest radiographs or 25 chest computed tomography scans.","s":6},{"t":"★ Pregnancy test","d":"\"Always, always, always\": beta human chorionic gonadotropin (urine or blood) on every female of childbearing age. Pregnancy is NOT an absolute contraindication; emergent imaging is done, even with contrast.","s":6},{"t":"Lead shielding","d":"Everything not being filmed, especially thyroid, ovaries, testes, breasts, fetus.","s":6},{"t":"★ Contrast cautions","d":"Anaphylaxis to medicines; ★ SHELLFISH anaphylaxis not yet tested for iodine allergy; iodine anaphylaxis or angioedema; HIGH CREATININE or blood urea nitrogen (renally cleared, NEPHROTOXIC); suspected THYROID dysfunction.","s":6},{"t":"Magnetic resonance precautions","d":"Metal implants that are NOT titanium; gadolinium allergy (rare); claustrophobia.","s":6},{"t":"Planes","d":"TRANSVERSE (axial) = cross-section; FRONTAL (coronal) = both lungs, apex to base; SAGITTAL = one side in profile. A slice, not a stacked shadow.","s":7},{"t":"Attenuation","d":"HIGH (bright): bone (very high), FRESH blood, contrast. LOW (dark): air and gas, fluid, coagulated blood. NORMAL: heart and muscle.","s":7},{"t":"Angiogram pearls","d":"DESCENDING AORTA always on the LEFT of the patient's vertebral column; patient's left = YOUR right; RIGHT ventricle nearest the sternum; LEFT ventricle has the thickest wall; for an embolism the PULMONARY ARTERIES matter most.","s":7},{"t":"Clot","d":"A dark filling defect inside a bright, contrast-filled pulmonary artery.","s":7},{"t":"Vasculogram","d":"Almost always a computed tomography angiogram: embolism, pulmonary hypertension, vasculitis, scleroderma.","s":7},{"t":"Pneumonia","d":"CONSOLIDATION (infiltrate): white, filled-in lung where it should be dark. Don't sort bacterial from viral on the film.","s":8},{"t":"★ Pleural effusion","d":"BLUNTED costophrenic angles; on computed tomography a gray collection compressing the lung.","s":8},{"t":"★ Pulmonary edema","d":"CEPHALIZATION of vessels, KERLEY B LINES (short horizontal lines at the outer lower lungs from thickened INTERLOBULAR SEPTA), pleural effusion, INCREASED cardiothoracic ratio.","s":8},{"t":"Pneumothorax","d":"JET BLACK air with the COMPRESSED lung beside it.","s":8},{"t":"★ Interstitial lung disease","d":"Diffuse abnormal patterns in the INTERSTITIUM, not the air sacs. Computed tomography: reticular (net-like), nodular (dots), HONEYCOMBING (cysts 3 to 10 millimeters), volume loss, traction bronchiectasis, GROUND-GLASS (hazy, pale), Kerley B lines.","s":8},{"t":"The frame","d":"Pulmonary function tests measure FLOW (how air moves), VOLUME (how much the lungs hold) and GAS TRANSFER (how well gas crosses into the blood).","s":9},{"t":"★ Whole-body plethysmography","d":"The glass booth. Measures the total lung capacity, the functional residual capacity, the RESIDUAL VOLUME (\"the key thing\") and airway resistance.","s":9},{"t":"Spirometer","d":"Airflow and some lung volumes (handheld or desktop).","s":9},{"t":"Peak flow meter","d":"Peak expiratory flow; correlates with the forced expiratory volume in one second; bedside or home, as in asthma.","s":9},{"t":"Blood gas analyzer · pulse oximeter","d":"Gas exchange and oxygenation from a blood sample (pH, carbon dioxide and oxygen partial pressures, bicarbonate) · oxygen saturation and pulse rate from a fingertip clip (home use shown).","s":9},{"t":"Accurate testing","d":"Properly calibrated equipment (the calibration syringe), clean components and correct patient technique.","s":9},{"t":"★ The tracing","d":"\"See it in your sleep.\" A volume is one compartment; a capacity is a SUM of volumes.","s":10},{"t":"Tidal volume","d":"Each normal restful breath, about 500 mL.","s":10},{"t":"Inspiratory reserve volume","d":"Extra breathed IN on top of the tidal volume (3000 to 3300 mL).","s":10},{"t":"Expiratory reserve volume","d":"Extra breathed OUT after a normal breath out.","s":10},{"t":"Residual volume","d":"Air left after maximal expiration; can NEVER be breathed out (1200 mL).","s":10},{"t":"Inspiratory capacity","d":"Tidal + inspiratory reserve.","s":10},{"t":"Functional residual capacity","d":"Expiratory reserve + residual: air left at the end of a quiet breath out, muscles relaxed (2200 to 2400 mL).","s":10},{"t":"Vital capacity","d":"Tidal + inspiratory reserve + expiratory reserve: everything EXCEPT the residual volume (4500 to 5000 mL).","s":10},{"t":"Total lung capacity","d":"All four volumes: the maximum the lungs hold (5700 to 6200 mL).","s":10},{"t":"How it is done","d":"Inhale maximally, then exhale forcefully, as fast as possible, for at least 6 SECONDS. Repeated 3 times; the HIGHEST volumes and flows are recorded (the slide; the recording said \"average\").","s":11},{"t":"Forced vital capacity","d":"Total volume forcefully and rapidly exhaled after a maximal breath; reached in about 6 seconds.","s":11},{"t":"Forced expiratory volume in one second","d":"Air blown out in the FIRST SECOND.","s":11},{"t":"★ The ratio","d":"Forced expiratory volume in one second over forced vital capacity: the % of the forced vital capacity out in the first second. Normal more than 80%; below 70% = obstruction.","s":11},{"t":"★ The three most important values","d":"The forced vital capacity, the forced expiratory volume in one second and their ratio.","s":11},{"t":"Peak expiratory flow rate","d":"Maximum velocity of forced expiration: steepest slope of the volume-time curve, top of the flow-volume loop.","s":11},{"t":"Forced expiratory flow 25% to 75%","d":"Average flow over the middle half of the forced vital capacity.","s":11},{"t":"Normal volume-time curve","d":"Steep rise, then a plateau. Volume at 1 second = forced expiratory volume in one second; plateau = forced vital capacity.","s":11},{"t":"★ Normal flow-volume loop","d":"Expiratory limb above the axis, inspiratory below; quick rise to a sharp peak, then a STRAIGHT fall to the volume axis.","s":11},{"t":"Percent of predicted","d":"Forced expiratory volume in one second and forced vital capacity 80 to 100%; total lung capacity 80 to 120%; diffusing capacity more than 60%. Ranges are given on the exam.","s":11},{"t":"Diagnosis (most common)","d":"A pulmonary symptom: chronic shortness of breath, cough, unexplained hypercapnia or hypoxemia (smokers, occupational exposures).","s":12},{"t":"NOT a specific diagnosis","d":"They show the pathophysiological derangement and help rule out parts of the differential.","s":12},{"t":"Prognosis · surgical risk","d":"Prognosis of known disease · surgical risk before lung resection or with chronic obstructive pulmonary disease.","s":12},{"t":"Screening","d":"Early, asymptomatic complications of non-pulmonary disease (autoimmune disease) or of medication (long-term AMIODARONE).","s":12},{"t":"Three categories","d":"Obstructive, restrictive and pulmonary vascular (gas transfer impairment). NOT mutually exclusive (sarcoidosis can be all three).","s":13},{"t":"Obstructive","d":"Increased airway resistance; trouble getting air OUT. Chronic obstructive pulmonary disease, asthma, ★ BRONCHIECTASIS (permanent airway dilation), cystic fibrosis.","s":13},{"t":"Restrictive","d":"Decrease in VOLUME; trouble getting air IN. Poor compliance (interstitial lung disease, chest wall: obesity, kyphosis, scoliosis) or neuromuscular weakness (amyotrophic lateral sclerosis, muscular dystrophy).","s":13},{"t":"Gas transfer impairment","d":"Normal mechanics; the alveolar-capillary membrane or pulmonary blood flow. Pulmonary hypertension, chronic thromboembolic disease, early emphysema, early interstitial lung disease.","s":13},{"t":"★ The result table","d":"Obstruction: ratio DECREASED, below 70%. Restriction: forced vital capacity DECREASED, ratio normal or increased, 70% or more.","s":13},{"t":"★ Obstructive volume-time curve","d":"A slow rise and a long, late plateau (severe: no plateau, forced vital capacity reduced).","s":13},{"t":"★ Restrictive volume-time curve","d":"The normal shape at a LOWER volume: the air comes out easily, there is less of it.","s":13},{"t":"★ \"A scoop in the loop\"","d":"Obstruction: the expiratory limb is concave (COVING) after the peak; severe = low peak, long flat tail.","s":13},{"t":"★ \"A witch's hat\"","d":"Restriction: narrow, tall, sharp point; everything smaller; peak normal or mildly reduced, no coving.","s":13},{"t":"On the film","d":"Hyperinflated, flat diaphragms = obstruction. Small-volume lungs with reticular opacities = restriction (confirm with a low total lung capacity).","s":13},{"t":"★ Step 1","d":"The RATIO first. 70% is your marker.","s":14},{"t":"Ratio low","d":"Assess the forced vital capacity: normal = obstruction; low = obstruction or MIXED (severe obstruction lowers it too); check the total lung capacity.","s":14},{"t":"Ratio normal or high","d":"Assess the forced vital capacity: low = possible restriction (confirm with lung volumes); normal = normal mechanics.","s":14},{"t":"Mixed defect","d":"Low ratio AND low total lung capacity.","s":14},{"t":"Case 1 (no audio)","d":"Smoker: ratio 52% (low), forced vital capacity 61%, total lung capacity 120% (not low) = OBSTRUCTION, scooped loop; little change after albuterol.","s":14},{"t":"Case 2 (no audio)","d":"Animal trainer, crackles, saturation 88%: ratio 94%, forced vital capacity 39%, total lung capacity 44% = RESTRICTION; diffusing capacity LOW (38%): the membrane is affected.","s":14},{"t":"Case 3 (no audio)","d":"Spinal cord injury, clear lungs: ratio normal, forced vital capacity 71%, total lung capacity 67% = RESTRICTION; diffusing capacity NORMAL (97%): the membrane is intact.","s":14},{"t":"Spirometry with the flow-volume loop","d":"Diagnoses OBSTRUCTIVE disease.","s":15},{"t":"Lung volumes","d":"Diagnose RESTRICTIVE disease (the total lung capacity confirms restriction).","s":15},{"t":"Diffusing capacity for carbon monoxide","d":"Integrity of the alveolar-capillary membrane: diagnoses PULMONARY VASCULAR disease. Normal spirometry and volumes with a suspected gas transfer problem: order this next.","s":15},{"t":"What the tests examine","d":"Airways, parenchyma, pulmonary vasculature, the bellows (diaphragm and chest wall) and the neural control of ventilation.","s":15},{"t":"Specialized tests","d":"Arterial blood gas; exercise oximetry; six-minute walk; peak flow; maximal inspiratory and expiratory pressures (diaphragmatic strength).","s":15},{"t":"Six-minute walk test","d":"Walk as far as possible in 6 minutes: monitors response to treatment AND prognosis.","s":15},{"t":"Exercise oximetry","d":"Oxygenation at rest and with modest activity; quick and cheap.","s":15},{"t":"Oxygenation","d":"Pulse oximeter (fingertip) and the blood gas analyzer; the arterial blood gas is a SPECIALIZED test, not a standard one.","s":15}],"map":{"principles-of-diagnostic-medicine-i-exam-4-pulmonary-function-testing-quiz-version-2":[70,61,80,89,94,69,71,54,81,75,99,93,71,106,71,-1,82,91,98,71,90,63,103,58,84,100,103,99,83,66],"principles-of-diagnostic-medicine-i-exam-4-pulmonary-function-testing-quiz":[99,87,56,70,71,71,71,81,74,67,-1,72,104,77,89,54,105,83,88,75,60,62,71,76,73,99,64,57,95,84],"principles-of-diagnostic-medicine-i-exam-4-pulmonary-imaging-quiz-version-2":[39,33,51,20,20,21,11,27,25,50,-1,43,14,35,46,52,9,45,34,17,48,45,13,5,49,34,10,36,32,29],"principles-of-diagnostic-medicine-i-exam-4-pulmonary-imaging-quiz":[29,36,52,6,34,24,-1,13,20,15,29,14,22,4,33,11,48,51,35,45,12,49,30,50,38,39,41,26,16,29]}};
